import{_ as s,l,o as e,c as n,v as r,p as i,x as o,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"Las Vegas 与 Monte Carlo","description":"","frontmatter":{"title":"Las Vegas 与 Monte Carlo","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/las-vegas-monte-carlo.md","filePath":"cs/las-vegas-monte-carlo.md","lastUpdated":1789023840000}'),p={name:"cs/las-vegas-monte-carlo.md"};function m(C,a,E,g,_,B){const t=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="las-vegas-与-monte-carlo" tabindex="-1">Las Vegas 与 Monte Carlo <a class="header-anchor" href="#las-vegas-与-monte-carlo" aria-label="Permalink to &quot;Las Vegas 与 Monte Carlo&quot;">​</a></h1><div class="epigraph"><p>Las Vegas 永远正确、时间随机；Monte Carlo 限时、以小概率错。重复与双边错误把 RP/BPP 与期望多项式分开。</p><footer>—— 据 Motwani and Raghavan, Randomized Algorithms, 1995；[随机化算法直觉](/cs/randomized-algo)；CLRS 第 5 章整理</footer></div><p>上一课<a href="/cs/karger-min-cut">Karger 最小割</a>是典型 Monte Carlo：可能报更大的割。主干已分两类。本课缺口是<strong>钉术语</strong>并接上 Karger、rho、指纹：何时可变成 Las Vegas（有验证器）。不重写指示器。后课 Freivalds 指纹。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Las Vegas：输出正确，如随机快排、随机增量几何（期望 \\(O(n\\log n)\\)）。可中止重来，期望时间有界。Monte Carlo：Karger、Miller–Rabin（单侧）、指纹相等（碰撞则可能错）。单侧错误可重复压概率。有确定性多项式验证（NP 证书或最小割再检查）则 MC 可改 LV：错就重抽，直到验证过。</p><p>缺口是分类，不是新算法。</p><h3 id="期望多项式不是最坏多项式" tabindex="-1">期望多项式不是最坏多项式 <a class="header-anchor" href="#期望多项式不是最坏多项式" aria-label="Permalink to &quot;期望多项式不是最坏多项式&quot;">​</a></h3><p>LV 最坏可很长。MC 最坏时间固定。不要把「平均输入」与「算法内硬币」混。</p><p><span class="marginnote">Motwani–Raghavan。RP：单侧错；BPP 双侧。本课算法，复杂度类点名。后课 Freivalds 是 MC 矩阵乘检验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写算法时声明：错从哪来、能否验证、重复几次。Karger：可用流验证全局割是否等于报的值（对无向）。指纹：碰撞无法本地验证相等。</p>',11)),(e(),i(c,null,{default:o(()=>[h(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LV%5B%22%E6%B0%B8%E8%BF%9C%E5%AF%B9%EF%BC%8C%E6%97%B6%E9%97%B4%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20EX%5B%22%E6%9C%9F%E6%9C%9B%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20MC%5B%22%E9%99%90%E6%97%B6%EF%BC%8C%E5%8F%AF%E9%94%99%22%5D%20--%3E%20REP%5B%22%E9%87%8D%E5%A4%8D%E5%8E%8B%E5%A4%B1%E8%B4%A5%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>错误概率对最坏输入取，不是平均实例。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重复 \\(k\\) 次独立，失败 \\((1-p)^k\\)。双侧错误要 Chernoff 或多数票。与近似比：随机近似给期望比或高概率比，后课。与在线：在线没有「重复整个输入」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 \\(P=BPP?\\)。不写全部 RP 完全问题。后课默认：先分 LV/MC 再分析。下一课指纹与 Freivalds。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LV 正确；MC 可错可限时。</li><li>有验证器则 MC 可改 LV。</li><li>Karger 是 MC；快排是 LV。</li><li>出处：Motwani and Raghavan, 1995；CLRS。</li></ul>',7))])}const f=s(p,[["render",m]]);export{P as __pageData,f as default};
